function Logo(){return <span className="logo"><span className="logo-mark">cd<span/></span><span className="logo-word">CD <b>systems</b><small>INDUSTRIAL SOURCING</small></span></span>}
function Photo({name,alt,className='',priority=false}:{name:string;alt:string;className?:string;priority?:boolean}){return <img src={`/images/${name}.jpg`} alt={alt} className={className} loading={priority?'eager':'lazy'} decoding="async"/>}
function Heading({kicker,title,text,children}:{kicker?:string;title:string;text?:string;children?:ReactNode}){return <div className="section-heading"><div>{kicker&&<p className="eyebrow">{kicker}</p>}<h2>{title}</h2>{text&&<p>{text}</p>}</div>{children}</div>}
