const [compare,setCompare]=useState<string[]>([]),[mobile,setMobile]=useState(false),[searchText,setSearchText]=useState(''),[searchType,setSearchType]=useState('produits'),[country,setCountry]=useState(''),[category,setCategory]=useState(''),[maxMoq,setMaxMoq]=useState(''),[maxDays,setMaxDays]=useState(''),[sort,setSort]=useState('pertinence'),[listMode,setListMode]=useState(false),[filtersOpen,setFiltersOpen]=useState(false),[page,setPage]=useState(1),[draftDetail,setDraftDetail]=useState<Draft|null>(null);
const [rfqStep,setRfqStep]=useState(1),[rfqId,setRfqId]=useState(''),[savedRfq,setSavedRfq]=useState(false),[rfq,setRfq]=useState({title:'',quantity:'',unit:'pièces',destination:'France',deadline:'',details:'',company:'',email:'',productId:''});
const [supplierDone,setSupplierDone]=useState(false),[applicationId,setApplicationId]=useState('');
const refresh=useCallback(async()=>{setLoading(true);try{const r=await fetch('/api/workspace',{cache:'no-store'});if(r.status===401){setWorkspace({user:null,favorites:[],drafts:[]});return;}const data=await r.json() as Workspace & {error?:string};if(!r.ok)throw new Error(data.error);setWorkspace(data);setError('');}catch(e){setError(e instanceof Error?e.message:'Espace indisponible');}finally{setLoading(false)}},[]);
useEffect(()=>{void refresh()},[refresh]);
useEffect(()=>{setMobile(false);setFiltersOpen(false);setPage(1);if(path!=='/demande-de-devis'){setSavedRfq(false);setRfqStep(1);setRfqId('')}window.scrollTo({top:0});},[path]);
useEffect(()=>{setSearchText(search.get('q')||'');setCountry(search.get('pays')||'');setCategory(search.get('secteur')||'');setPage(1)},[search]);
useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(timer)},[toast]);
useEffect(()=>{const id=search.get('produit');if(path==='/demande-de-devis'&&id){const p=products.find(x=>x.id===id);if(p)setRfq(r=>({...r,title:p.name,quantity:String(p.moq),unit:p.unit+'s',productId:p.id}));}},[path,search]);
useEffect(()=>{const context=(document as Document&{modelContext?:{registerTool:(tool:unknown,options:unknown)=>void}}).modelContext;if(!context)return;const lifecycle=new AbortController();try{context.registerTool({name:'search_industrial_catalogue',title:'Rechercher dans le catalogue CD systems',description:'Navigate to industrial demo product results. Does not contact suppliers or create orders.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:unknown)=>{if(!input||typeof input!=='object'||!('query'in input)||typeof input.query!=='string'||input.query.length>200)throw new Error('Requête invalide');router.push('/catalogue?q='+encodeURIComponent(input.query));return{destination:'catalogue',query:input.query,demo:true}}},{signal:lifecycle.signal})}catch(e){console.warn('WebMCP unavailable',e)}return()=>lifecycle.abort()},[router]);
async function write(body:unknown){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json() as {error?:string;ok?:boolean;id?:string};if(!r.ok)throw new Error(d.error||'Enregistrement impossible');return d}
async function favorite(id:string){if(!workspace.user){setToast('Connectez-vous à votre espace pour enregistrer une sélection.');return;}if(pendingFavorites.includes(id))return;setPendingFavorites(a=>[...a,id]);const selected=!workspace.favorites.includes(id);try{await write({action:'favorite',productId:id,selected});setWorkspace(w=>({...w,favorites:selected?[...w.favorites,id]:w.favorites.filter(x=>x!==id)}));setToast(selected?'Produit enregistré dans votre sélection.':'Produit retiré de votre sélection.')}catch(e){setToast(String((e as Error).message))}finally{setPendingFavorites(a=>a.filter(x=>x!==id))}}
function toggleCompare(id:string){if(compare.includes(id))setCompare(compare.filter(x=>x!==id));else if(compare.length<3)setCompare([...compare,id]);else setToast('Vous pouvez comparer jusqu’à 3 produits. Retirez-en un pour continuer.')}
function startRfq(p?:Product){setSavedRfq(false);setRfqStep(1);setRfqId(crypto.randomUUID());setError('');if(p)setRfq(r=>({...r,title:p.name,quantity:String(p.moq),unit:p.unit+'s',productId:p.id}));router.push('/demande-de-devis'+(p?'?produit='+p.id:''))}
