function renderProduct(p:Product){const s=getSupplier(p.supplierId);return <article key={p.id} className="product-card"><Link href={'/produits/'+p.id} className="product-photo"><Photo name={p.image} alt={`Illustration du secteur ${getSector(p.category).name}`}/><span className="photo-label">{p.process}</span></Link><button className={'favorite '+(workspace.favorites.includes(p.id)?'selected':'')} onClick={()=>favorite(p.id)} disabled={pendingFavorites.includes(p.id)} aria-label={`Enregistrer ${p.name}`} aria-pressed={workspace.favorites.includes(p.id)}><Heart size={18} fill={workspace.favorites.includes(p.id)?'currentColor':'none'}/></button><div className="product-info"><div className="product-location"><MapPin size={12}/>{p.country}<span>FABRICATION SUR MESURE</span></div><h3><Link href={'/produits/'+p.id}>{p.name}</Link></h3><p className="product-material">{p.material}</p><Link className="manufacturer-link" href={'/fabricants/'+s.id}><span className="tiny-monogram">{s.initials}</span>{s.name}<ChevronRight size={13}/></Link><div className="product-price"><span>À partir de</span><strong>{euros(p.price)} <small>/ {p.unit}</small></strong></div><div className="product-facts"><span>Minimum <b>{p.moq.toLocaleString('fr-FR')} {p.unit}s</b></span><span>Délai indicatif <b>{p.days} jours</b></span></div><div className="product-actions"><Button variant="outline" onClick={()=>startRfq(p)}>Demander un devis <ArrowUpRight size={15}/></Button><label><input type="checkbox" checked={compare.includes(p.id)} onChange={()=>toggleCompare(p.id)}/>Comparer</label></div></div></article>}
function renderSupplier(id:string){const s=getSupplier(id);return <article key={id} className="supplier-card"><div className="supplier-top"><span className="monogram">{s.initials}</span><Pill muted>Profil démo</Pill></div><h3><Link href={'/fabricants/'+s.id}>{s.name}<ArrowUpRight size={17}/></Link></h3><p className="location"><MapPin size={14}/>{s.city}, {s.country}</p><p className="supplier-description">{s.description}</p><div className="tags">{s.processes.slice(0,2).map(t=><span key={t}>{t}</span>)}</div><div className="supplier-bottom"><span><Factory size={14}/> Fabricant</span><Link href={'/fabricants/'+s.id}>Voir l’entreprise <ArrowRight size={15}/></Link></div></article>}
function renderResources(){return <div className="resource-grid">{guides.map(g=><Link href={'/guides/'+g.id} className="resource-card" key={g.id}><Photo name={g.image} alt="Illustration industrielle"/><div><p className="eyebrow">{g.category} <span>{g.minutes} min de lecture</span></p><h3>{g.title}</h3><span className="text-link">Lire le guide <ArrowUpRight size={16}/></span></div></Link>)}</div>}
const query=(search.get('q')||'').toLowerCase();const sectorPath=path.startsWith('/secteurs/')?path.split('/')[2]:'';const countryPath=path.startsWith('/pays/')?countries.find(c=>c.code.toLowerCase()===path.split('/')[2])?.name:'';
const activeCategory=sectorPath||category,activeCountry=countryPath||country;
const results=products.filter(p=>(!activeCategory||p.category===activeCategory)&&(!activeCountry||p.country===activeCountry)&&(!maxMoq||p.moq<=Number(maxMoq))&&(!maxDays||p.days<=Number(maxDays))&&(!query||`${p.name} ${p.material} ${p.process} ${getSector(p.category).name} ${getSupplier(p.supplierId).name}`.toLowerCase().includes(query))&&(path!=='/selection'||workspace.favorites.includes(p.id))).sort((a,b)=>sort==='prix'?a.price-b.price:sort==='delai'?a.days-b.days:sort==='minimum'?a.moq-b.moq:0);
const product=path.startsWith('/produits/')?products.find(p=>p.id===path.split('/')[2]):undefined;
